// Demo "irregular casino" (v2): two floors that each COMBINE gaming + back-of-
// house on one map. A curved serpentine main aisle (customer route, no right
// angles) extends into a straight service spur reaching a rectangular BOH
// (Count Room / Vault / Surveillance / Security / Receiving, or admin upstairs).
// Gaming reads as real elements: a curved table-games strip hugging the aisle
// with rectangular slot banks behind, enclosed Poker / High-Limit rooms, a
// rounded Bar and Cage, Sportsbook. ~91 cameras by casino doctrine give ~96%
// mean room coverage per floor. Generated by scratch/_scratch-gen-casino.mjs.

/** Axis-aligned rectangle as a 4-vertex polygon (open ring). */
export function rectPoly(x0: number, y0: number, x1: number, y1: number): MetreXY[] {
  return [
    [x0, y0],
    [x1, y0],
    [x1, y1],
    [x0, y1],
  ];
}

/** A rectangle polygon from any two drag corners. */
export function rectFromDrag(a: MetreXY, b: MetreXY): MetreXY[] {
  return rectPoly(
    Math.min(a[0], b[0]),
    Math.min(a[1], b[1]),
    Math.max(a[0], b[0]),
    Math.max(a[1], b[1]),
  );
}

